    h = ('<div><span class="hint" style="font-weight:600;letter-spacing:.06em">SUPERADMIN · ORGANIZACIONES</span><h1 style="margin:2px 0 0;font-size:22px;font-weight:700">Altas de miembros</h1><span class="hint" style="font-size:12.5px">Cada vez que alguien se une a una empresa te llega un aviso. Las verificaciones manuales necesitan tu aprobación.</span></div>'
         '<div style="display:flex;gap:6px"><span class="chip" style="background:' + AZ + ';border-color:' + AZ + ';color:#FFFFFF">Hoy · 7</span><span class="chip">Pendientes · 1</span><span class="chip">Todas</span></div>' +
         ''.join('<div class="card" style="gap:6px"><div style="display:flex;gap:10px;align-items:center"><span style="width:34px;height:34px;border-radius:50%;background:' + SOFT + ';color:' + AZ + ';font-size:11px;font-weight:600;display:flex;align-items:center;justify-content:center;flex:none">' + a + '</span><span style="flex:1;min-width:0;display:flex;flex-direction:column"><strong style="font-size:13.5px">' + n + '</strong><span class="hint">' + o + '</span></span>' + s + '</div><span class="hint" style="font-size:12px">' + c + '</span><span class="' + ('btnp' if b == 'Aprobar' else 'btn') + '" style="height:34px;align-self:flex-start;' + ('background:' + AZ if b == 'Aprobar' else '') + '">' + b + '</span></div>' for a, n, o, c, s, b in alt) +
         '<span class="hint">Los administradores de cada empresa reciben el mismo aviso y pueden quitar el acceso. Tú puedes revertir cualquier alta.</span>')
