B = {'MB_FD_Distribuidores': ('Móvil · D4 · Distribuidores', 1180, distribuidores()), 'MB_FD_FichaDistribuidores': ('Móvil · Ficha · pestaña Distribuidores (lo que ve el comprador)', 1100, ficha()),
     'MB_FD_Expertos': ('Móvil · D5 · Expertos recomendados', 1060, expertos()), 'MB_FD_Contenidos': ('Móvil · D6 · Contenidos', 1260, contenidos()),
     'MB_FD_AvisoEmpresa': ('Móvil · D0c · Aviso a los administradores', 980, aviso_empresa()), 'MB_FD_AvisoAdmin': ('Móvil · D0d · Altas de miembros (superadmin)', 1100, aviso_admin())}
if __name__ == '__main__':
    alt = json.load(open(sys.argv[2])) if len(sys.argv) > 2 else {}
    for k, (t, h, b) in B.items():
        html = wrap(t, alt.get(k, h), b)
        open(DEST + k + '.dc.html', 'w').write(html); open(W + '/project/' + k + '.dc.html', 'w').write(html)
    print('ok', len(B))
